    public static ImmutableArray<TrainerId> SourceTrainers { get; }=Expected.Keys.OrderBy(x=>x.Value,StringComparer.Ordinal).ToImmutableArray();
    public static ImmutableArray<TrainerId> SupportedTrainers { get; }=Expected.Where(x=>!x.Value.Double).Select(x=>x.Key).OrderBy(x=>x.Value,StringComparer.Ordinal).ToImmutableArray();
    public static ImmutableArray<TrainerId> DeferredDoubleTrainers { get; }=Expected.Where(x=>x.Value.Double).Select(x=>x.Key).OrderBy(x=>x.Value,StringComparer.Ordinal).ToImmutableArray();
    public static void ValidateCatalog(FuchsiaRouteTrainerCatalog catalog)
    {
        ArgumentNullException.ThrowIfNull(catalog);
        if(catalog.SourceCommit!=SourceCommit||catalog.Profile!=RulesVersion||catalog.CompleteSourceRoster||catalog.Trainers is null||catalog.Battles is null||catalog.InitialMoves is null||catalog.Trainers.Count!=40||catalog.Battles.Count!=43||catalog.InitialMoves.Count!=40)
            throw new NotSupportedException("Exact40-team/43-entry Fuchsia source catalog required.");
        foreach(var (id,e) in Expected)
        {
            if(!catalog.Trainers.TryGetValue(id,out var t)||t is null||t.Id!=id||t.SourceTrainerId!=e.Id||t.SourceTrainerName!=e.Name||
                t.EncodedTrainerName.IsDefault||!t.EncodedTrainerName.SequenceEqual(e.Encoded)||t.TrainerClass!=e.Class||t.SourceTrainerClass!=e.ClassId||t.TrainerPic!=e.Pic||t.SourceTrainerPic!=e.PicId||
                t.EncounterMusicGender!=e.Gender||t.BaseMoney!=e.Money||t.PartyFlags!=e.Flags||t.DoubleBattle!=e.Double||t.AiFlags!=1||t.AiFlagSymbols.IsDefault||!t.AiFlagSymbols.SequenceEqual(["AI_SCRIPT_CHECK_BAD_MOVE"])||
                t.Items.IsDefault||!t.Items.SequenceEqual(Enumerable.Repeat("ITEM_NONE",4))||t.Party.IsDefault||t.Party.Length!=e.Party.Length||!catalog.InitialMoves.TryGetValue(id,out var initial)||initial.IsDefault||initial.Length!=e.Party.Length)
                throw new NotSupportedException("Fuchsia trainer metadata differs.");
            for(int i=0;i<e.Party.Length;i++)
            {
                var p=t.Party[i];var m=e.Party[i];
                if(p is null||p.Species.Value!=m.Species||p.SourceSpeciesId!=m.Source||p.Level!=m.Level||p.SourceIv!=m.Iv||p.SpeciesName!=m.Name||p.EncodedSpeciesName.IsDefault||!p.EncodedSpeciesName.SequenceEqual(m.Encoded)||
                    p.HeldItem!=m.Item||p.CustomMoves.IsDefault||!p.CustomMoves.Select(x=>x.Value).SequenceEqual(m.Custom)||initial[i].IsDefault||!initial[i].Select(x=>x.Value).SequenceEqual(m.Initial))
                    throw new NotSupportedException("Fuchsia source party or resolved move slots differ.");
            }
        }
        foreach(var (script,e) in Entries)
        {
            if(!catalog.Battles.TryGetValue(script,out var b)||b is null||b.ScriptEntry!=script||b.Trainer.Value!=e.Trainer||b.Mode!=e.Mode||b.RivalFlags!=0||b.BattleTypeFlags!=e.Flags||
                b.IntroText!=e.Intro||b.DefeatText!=e.Defeat||b.PostBattleText!=e.Post||b.EntryScript!=e.EntryScript||b.VictoryText!=""||b.Callback!="CB2_EndTrainerBattle"||b.PostBattleScript is not null||b.MusicOption is not null||b.Source.Path!="data/scripts/trainers.inc")
                throw new NotSupportedException("Fuchsia original battle entry differs.");
        }
    }
    internal static bool ValidPartyMember(PokemonCatalog catalog,PokemonInstance mon,TrainerId id,uint? flags=null)
    {
        if(!Expected.TryGetValue(id,out var e)||e.Double||flags is {} f&&f!=1)return false;
        uint hash=0;
        foreach(var p in e.Party)
        {
            foreach(int b in e.Encoded.Concat(p.Encoded))hash=unchecked(hash+(uint)b);
            uint personality=unchecked(((e.Gender&128)!=0?0x78u:0x88u)+(hash<<8));int iv=p.Iv*31/255;
            if(mon.Species.Value!=p.Species||mon.SourceSpeciesId!=p.Source||mon.Level!=p.Level||mon.Personality!=personality||mon.Ivs!=new SixStats(iv,iv,iv,iv,iv,iv)||mon.Evs!=SixStats.Zero||mon.Moves.IsDefault||mon.Moves.Any(m=>m.PpUps!=0))continue;
            if(catalog.Species.Count==107&&mon.Moves.Select(m=>m.Move.Value).SequenceEqual(p.Initial.TakeWhile(m=>m!="pret:MOVE_NONE")))return true;
        }
        return false;
    }
    public static TrainerPartyCreationResult Create(FuchsiaRouteTrainerCatalog trainers,PokemonCatalog pokemon,TrainerId id,RngState rng)
    {
        ValidateCatalog(trainers);
        if(!trainers.Trainers.TryGetValue(id,out var trainer))throw new NotSupportedException("Unknown Fuchsia route trainer.");
        if(trainer.DoubleBattle)throw new NotSupportedException("fuchsia_route_preset_double_requires_2v2");
        PokemonFactory.ValidateCatalog(pokemon);
        if(pokemon.Species.Count!=107)throw new NotSupportedException("Fuchsia route trainer requires exact107 species.");
        var expected=trainers.InitialMoves[id];
        for(int i=0;i<trainer.Party.Length;i++)
        {
            var p=trainer.Party[i];var source=pokemon.Species[p.Species];
            if(expected[i].Any(m=>m.Value!="pret:MOVE_NONE"&&!pokemon.Moves.ContainsKey(m)))throw new NotSupportedException("Fuchsia source move metadata missing.");
            if((trainer.PartyFlags&1)==0&&!PokemonMoveRules.InitialMoves(pokemon,source,p.Level).Select(m=>m.Move).SequenceEqual(expected[i]))throw new NotSupportedException("Fuchsia source natural slots differ.");
        }
        var made=TrainerPartyFactory.CreateValidated(trainer,pokemon,rng);
        if((trainer.PartyFlags&1)==0)return made;
        return made with {Party=made.Party.Select((p,i)=>p with {Pokemon=p.Pokemon with {Moves=trainer.Party[i].CustomMoves.TakeWhile(m=>m.Value!="pret:MOVE_NONE").Select(m=>new PokemonMoveSlot(m,pokemon.Moves[m].Pp,pokemon.Moves[m].Pp)).ToImmutableArray()}}).ToImmutableArray()};
    }
